import java.io.*;
import java.util.*;

public class Main {
    static boolean isUndoubtedlyLucky(int num) {
        if (num == 0) return true; // though 0 not used as positive, just safety
        boolean[] present = new boolean[10];
        int cnt = 0;
        int x = num;
        while (x > 0) {
            int d = x % 10;
            if (!present[d]) {
                present[d] = true;
                cnt++;
                if (cnt > 2) return false;
            }
            x /= 10;
        }
        return true;
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        long n = Long.parseLong(br.readLine().trim());
        long count = 0;
        for (int i = 1; i <= n; i++) {
            if (isUndoubtedlyLucky(i)) count++;
        }
        System.out.println(count);
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

public class Main {
    static long n;
    static long count = 0;

    static void dfs(long cur, int d1, int d2) {
        if (cur > n) return;
        if (cur != 0) count++;
        if (cur == 0) {
            if (d1 == -1 && d2 == -1) {
                for (int i = 0; i <= 9; i++) {
                    dfs(i, i, -1);
                }
            } else if (d1 != -1 && d2 == -1) {
                dfs(cur * 10 + d1, d1, -1);
            }
            return;
        }
        if (d1 != -1 && d2 == -1) {
            dfs(cur * 10 + d1, d1, -1);
            for (int d = 0; d <= 9; d++) {
                if (d != d1) {
                    dfs(cur * 10 + d, d1, d);
                }
            }
        } else if (d1 != -1 && d2 != -1) {
            dfs(cur * 10 + d1, d1, d2);
            dfs(cur * 10 + d2, d1, d2);
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        n = Long.parseLong(br.readLine().trim());
        dfs(0, -1, -1);
        System.out.println(count);
    }
}

