public class Main {
    static long n;
    static long count = 0;

    static void dfs(long cur, boolean[] used) {
        if (cur > n) return;
        if (cur != 0) {
            int mask = 0;
            long tmp = cur;
            while (tmp > 0) {
                int d = (int)(tmp % 10);
                mask |= (1 << d);
                if (Integer.bitCount(mask) > 2) return;
                tmp /= 10;
            }
            count++;
        }
        for (int d = 0; d <= 9; d++) {
            long next = cur * 10 + d;
            if (next == 0) continue;
            if (next > n) continue;
            dfs(next, used);
        }
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        n = Long.parseLong(br.readLine().trim());
        dfs(0, new boolean[10]);
        System.out.println(count);
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

public class Main {
    static long n;
    static long count = 0;

    static void dfs(long cur, int d1, int d2, boolean used1, boolean used2) {
        if (cur > n) return;
        if (cur != 0 && used1 && used2) count++;
        for (int d = 0; d <= 9; d++) {
            long next = cur * 10 + d;
            if (next == 0) continue; // no leading zero, and positive integers only
            boolean nu1 = used1, nu2 = used2;
            if (!used1) {
                nu1 = true;
                dfs(next, d, d2, nu1, nu2);
            } else if (!used2) {
                if (d == d1) {
                    dfs(next, d1, d2, nu1, nu2);
                } else {
                    nu2 = true;
                    dfs(next, d1, d, nu1, nu2);
                }
            } else {
                if (d == d1 || d == d2) {
                    dfs(next, d1, d2, nu1, nu2);
                }
            }
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        n = Long.parseLong(br.readLine().trim());
        dfs(0, -1, -1, false, false);
        // All numbers with only one distinct digit are also undoubtedly lucky
        // They were not counted in dfs because it requires both digits used
        // So we add them separately.
        for (int d = 0; d <= 9; d++) {
            long val = d;
            while (val <= n && val != 0) {
                count++;
                if (val > (n - d) / 10) break;
                val = val * 10 + d;
            }
        }
        System.out.println(count);
    }
}

