import java.io.*;
import java.util.*;

public class Main {
    static long n;
    static long count = 0;

    static void dfs(long cur, boolean[] used) {
        if (cur > n) return;
        if (cur != 0) {
            int diff = 0;
            for (boolean b : used) if (b) diff++;
            if (diff <= 2) count++;
        }
        for (int d = 0; d <= 9; d++) {
            long next = cur * 10 + d;
            if (next == 0) continue; // no leading zero
            if (next > n) continue;
            boolean[] nextUsed = Arrays.copyOf(used, 10);
            nextUsed[d] = true;
            int diff = 0;
            for (boolean b : nextUsed) if (b) diff++;
            if (diff > 2) continue;
            dfs(next, nextUsed);
        }
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        n = Long.parseLong(br.readLine().trim());
        boolean[] used = new boolean[10];
        dfs(0, used);
        System.out.println(count);
    }
}

