import java.io.*;
import java.util.*;

public class Main {
    static boolean isUndoubtedlyLucky(int num) {
        if (num == 0) return true; // 0 has only digit 0, so it's undoubtedly lucky
        boolean[] present = new boolean[10];
        while (num > 0) {
            present[num % 10] = true;
            num /= 10;
        }
        int count = 0;
        for (boolean b : present) if (b) count++;
        return count <= 2;
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        long n = Long.parseLong(br.readLine().trim());
        int limit = (int) n;
        int count = 0;
        for (int i = 1; i <= limit; i++) {
            if (isUndoubtedlyLucky(i)) count++;
        }
        System.out.println(count);
    }
}
